def norm(cells):
    rs=[y for y,x in cells]; cl=[x for y,x in cells]
    return frozenset((y-min(rs),x-min(cl)) for y,x in cells), (max(rs)-min(rs)+1, max(cl)-min(cl)+1)
def transforms(cells):
    s=norm(cells)[0]
    res=set()
    for k in range(4):
        t=frozenset((c,-y) for y,c in s)  # rot90
        # normalize each
        def n(ss):
            m=min(y for y,x in ss); n2=min(x for y,x in ss)
            return frozenset((y-m,x-n2) for y,x in ss)
        res.add(n(t))
        res.add(n(frozenset((y,-x) for y,x in t)))
        s=t
    return res
