def syms(cells):
    s = set(cells); m=min(y for y,x in s); n=min(x for y,x in s)
    s = frozenset((y-m,x-n) for y,x in s)
    res=set()
    cur=s
    for k in range(4):
        res.add(cur)
        res.add(frozenset((y,-x) for y,x in cur))
        cur = frozenset((x,-y) for y,x in cur)
    def nrm(ss):
        m=min(y for y,x in ss); n=min(x for y,x in ss)
        return frozenset((y-m,x-n) for y,x in ss)
    return {nrm(r) for r in res}
